dtsPropsFor.Structure:
/** Shown in the header and used as the .schematic file name. */
name: string;
/** [width (x, west→east), height (y, up), length (z, north→south)]. */
size: [number, number, number];
/** Height of the 3D view in px. Default 520. */
viewHeight?: number;
/** Hide the material list. */
hideMaterials?: boolean;
children?: React.ReactNode;

dtsPropsFor.Block:
/** "registry:name@meta", e.g. "minecraft:stonebrick@0". */
block: string;
/** [x, y, z] inside the Structure size. */
at: [number, number, number];
/** Raw world metadata, overriding the shape direction rules. Rarely needed. */
meta?: number;

dtsPropsFor.Fill:
block: string;
/** One corner, inclusive. */
from: [number, number, number];
/** Opposite corner, inclusive. */
to: [number, number, number];

dtsPropsFor.Air:
/** One corner (or the single block when to is omitted). */
from: [number, number, number];
/** Opposite corner, inclusive. */
to?: [number, number, number];

dtsPropsFor.Hollow:
block: string;
/** One corner, inclusive. */
from: [number, number, number];
/** Opposite corner, inclusive. */
to: [number, number, number];
/** Leave the floor layer out. */
noFloor?: boolean;
/** Leave the ceiling layer out. */
noCeiling?: boolean;

dtsPropsFor.Stairs:
block: string;
at: [number, number, number];
/** End of a straight run (inclusive), all with the same facing. */
to?: [number, number, number];
/** The side the tall back of the step is on — the direction you walk to go up. */
facing: "north" | "south" | "east" | "west";
/** Hang the step from the ceiling (tall part at the bottom). */
upsideDown?: boolean;

dtsPropsFor.Slab:
block: string;
at: [number, number, number];
/** Opposite corner of a box of slabs, inclusive. */
to?: [number, number, number];
/** Upper half of the block space instead of the lower half. */
top?: boolean;

dtsPropsFor.Pillar:
block: string;
at: [number, number, number];
/** End of a straight run, inclusive. */
to?: [number, number, number];
/** Direction the log/pillar runs. Default "y" (upright). */
axis?: "x" | "y" | "z";

dtsPropsFor.Door:
block: string;
/** Position of the lower half;
the upper half goes directly above. */
at: [number, number, number];
/** Direction you face walking in through the door. */
facing: "north" | "south" | "east" | "west";
hingeRight?: boolean;

dtsPropsFor.Torch:
/** Defaults to "minecraft:torch@0". */
block?: string;
at: [number, number, number];
/** Where the supporting block is: "floor" or the wall direction from the torch. Default "floor". */
on?: "floor" | "north" | "south" | "east" | "west";
